class Solution:
    def minSwaps(self, grid) -> int:
        n = len(grid)
        max_right = [-1] * n
        for r, row in enumerate(grid):
            for c in range(n - 1, -1, -1):
                if row[c] == 1:
                    max_right[r] = c
                    break
        if all(v <= i for i, v in enumerate(sorted(max_right))):
            swaps = 0
            i = 0
            while i < n:
                while i < n and max_right[i] <= i:
                    i += 1
                if i == n:
                    break
                j = i
                while j < n and max_right[j] > i:
                    j += 1
                swaps += j - i
                max_right[i], max_right[i + 1: j + 1] = (max_right[j],
                                                         max_right[i: j])
                i += 1
            return swaps
        return -1

import itertools

class Solution:
    def minSwaps(self, grid) -> int:
        result = 0
        for target in reversed(range(1, len(grid))):
            row_idx = len(grid)-1-target
            while row_idx < len(grid):
                row = grid[row_idx]
                if not sum(itertools.islice(row, len(row)-target, len(row))):
                    break
                row_idx += 1
            else:
                return -1
            while row_idx != len(grid)-1-target:
                grid[row_idx], grid[row_idx-1] = grid[row_idx-1], grid[row_idx]
                result += 1
                row_idx -= 1
        return result

