class Solution:
    def findKthBit(self, n: int, k: int) -> str:
        i, s, hash_map = 1, '0', {'1': '0', '0': '1'}
        for i in range(1, n):
            s = s + '1' + ''.join((hash_map[i] for i in s))[::-1]
        return s[k-1]

class Solution:
    def findKthBit(self, n: int, k: int) -> str:
        flip, l = 0, 2**n-1
        while k > 1:
            if k == l//2+1:
                flip ^= 1
                break
            if k > l//2:
                k = l+1-k
                flip ^= 1
            l //= 2
        return str(flip)

